import{_ as e,c as p,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"坤下坤上 坤：","description":"京氏易傳 - 坤下坤上 坤：","frontmatter":{"title":"坤下坤上 坤：","description":"京氏易傳 - 坤下坤上 坤："},"headers":[],"relativePath":"classics/jingshi/034.md","filePath":"classics/jingshi/034.md"}'),i={name:"classics/jingshi/034.md"};function r(n,a,c,_,o,l){return t(),p("div",null,[...a[0]||(a[0]=[s('<h1 id="坤下坤上-坤" tabindex="-1">坤下坤上 坤： <a class="header-anchor" href="#坤下坤上-坤" aria-label="Permalink to “坤下坤上 坤：”">​</a></h1><p>純陰用事，象配地，屬土。柔道光也，陰凝感，與乾相納，臣奉君也。《易》雲：“黃裳，元吉”。六二，內卦陰處中</p><p>，臣道正也。與乾為飛伏，【癸酉金，壬戌土。】宗廟居世，三公為應。未免龍戰之災，無成有終。【陰臣陽君，臣不敢為</p><p>物之始。陽唱陰和，君命臣終其事也。】初六起履霜，至於堅冰。陰雖柔順，氣亦堅剛，為無邪氣也。</p><p>建始甲午至己亥，【芒種，小滿。】積算起己亥至戊戌，週而復始。【純土用事，入積算，定吉凶。】</p><p>五星從位起太陰，【太陰水星入卦】西南方之卦。【鎮星入卦配坤，西南。】星宿從位降癸酉金。【二十八宿，八卦星</p><p>宿，降坤上六癸酉金。】分氣候三十六。【起積為數三十六。】</p><p>陰中有陽，氣積萬象，故曰陰中陰。陰陽二氣，天地相接，人事吉凶，見乎其象。六位適變，八卦分焉。【六位變動，八</p><p>卦顯著。】陰雖虛納，於陽位稱實。【六五，六三之類也。】</p><p>升降反覆，不能久處，千變萬化，故稱乎易。易者，變也。陰極則陽來，陰消則陽長，衰則退，盛則戰。《易》雲：“上</p><p>六，龍戰於野，其血玄黃”。陽屬。【乾配西北積陰之的地，陰盛故戰，乾坤並處，天地之氣雜，稱玄黃也。】</p><p>陽來蕩陰，坤內卦初六適變入陽，曰震。陰盛陽微，漸來之義，故稱復。次降陽，入地雷復卦。</p>',12)])])}const h=e(i,[["render",r]]);export{f as __pageData,h as default};
